const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, '..', 'frontend', 'config', 'blog-content', 'fi');

function w(filename, obj) {
  // Build the file manually to get clean TypeScript output
  let s = `import type { BlogContent } from '../types';\n\nconst content: BlogContent = {\n`;
  s += `  seo: {\n`;
  s += `    primaryKeyword: '${esc(obj.seo.primaryKeyword)}',\n`;
  s += `    secondaryKeywords: [\n${obj.seo.secondaryKeywords.map(k => `      '${esc(k)}',`).join('\n')}\n    ],\n`;
  s += `    lsiKeywords: [\n${obj.seo.lsiKeywords.map(k => `      '${esc(k)}',`).join('\n')}\n    ],\n`;
  s += `    titleTag: '${esc(obj.seo.titleTag)}',\n`;
  s += `    metaDescription: '${esc(obj.seo.metaDescription)}',\n`;
  s += `  },\n`;
  s += `  hero: {\n`;
  s += `    title: '${esc(obj.hero.title)}',\n`;
  s += `    tagline: '${esc(obj.hero.tagline)}',\n`;
  s += `    description: '${esc(obj.hero.description)}',\n`;
  s += `  },\n`;
  s += `  category: '${obj.category}',\n`;
  s += `  introduction: '${esc(obj.introduction)}',\n`;
  s += `  sections: [\n`;
  for (const sec of obj.sections) {
    s += `    {\n      heading: '${esc(sec.heading)}',\n      content: '${esc(sec.content)}',\n    },\n`;
  }
  s += `  ],\n`;
  s += `  keyTakeaways: [\n${obj.keyTakeaways.map(k => `    '${esc(k)}',`).join('\n')}\n  ],\n`;
  s += `  faq: [\n`;
  for (const f of obj.faq) {
    s += `    {\n      question: '${esc(f.question)}',\n      answer: '${esc(f.answer)}',\n    },\n`;
  }
  s += `  ],\n`;
  s += `  internalLinks: [\n`;
  for (const l of obj.internalLinks) {
    s += `    { pageType: '${l.pageType}', slug: '${l.slug}', anchorText: '${esc(l.anchorText)}' },\n`;
  }
  s += `  ],\n`;
  s += `  relatedPosts: [\n`;
  for (const r of obj.relatedPosts) {
    s += `    { slug: '${r.slug}', title: '${esc(r.title)}' },\n`;
  }
  s += `  ],\n`;
  s += `  cta: {\n`;
  s += `    heading: '${esc(obj.cta.heading)}',\n`;
  s += `    description: '${esc(obj.cta.description)}',\n`;
  s += `    buttonText: '${esc(obj.cta.buttonText)}',\n`;
  s += `    buttonUrl: '${obj.cta.buttonUrl}',\n`;
  s += `  },\n`;
  s += `};\n\nexport default content;\n`;

  fs.writeFileSync(path.join(dir, filename), s, 'utf8');
  console.log('Wrote', filename);
}

function esc(s) {
  return s.replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, '\\n');
}

